  'ld.hidLose': '{b} ने अपने पासे नहीं दिखाए और एक पासा खो दिया।',
  'ld.end': '🏆 {b} ने झूठे का पासा जीत लिया!',
  'ld.gone': '{b} चले गए और खेल से बाहर हैं।',
  'ld.tooLow': 'पिछली बोली से ऊँची बोली लगाएँ: ज़्यादा पासे, या उतने ही पर ऊँचा अंक।',
  'ld.noOnes': 'इक्कों के वाइल्ड होने पर पहली बोली इक्कों पर नहीं हो सकती।',
  'ld.qAria': 'कितने',
  'ld.fAria': 'कौन सा अंक',
  'ld.bidBtn': 'बोली',
  'ld.callBtn': 'चुनौती!',
  'rules.ld': '🎲 झूठे का पासा (2–8 खिलाड़ी)\n\n[लक्ष्य] अंतिम खिलाड़ी जिसके पास पासे बचे हों, जीतता है।\n\n[शुरुआत] साइड पैनल में “झूठे का पासा शुरू करें” पर टैप करें; कमरे में ऑनलाइन सभी खेलेंगे। आप पहले “इक्कों को वाइल्ड मानें” (पेरूडो) पर टिक कर सकते हैं। हर किसी के पास 5 पासे होते हैं।\n\n[पासे फेंकना] हर राउंड की शुरुआत में सब एक साथ पासे फेंकते हैं, और सिर्फ़ आप अपने पासे देखते हैं। उन्हें देखने के लिए “मेरे पासे” पर टैप करें या दबाए रखें; वे आपकी स्क्रीन पर एक बार “🔒” से शुरू होकर भी दिखाए जाते हैं।\n\n[बोली] राउंड के पहले बोली लगाने वाले से शुरू करके, खिलाड़ी बारी-बारी से 45 सेकंड में खेलते हैं। अपनी बारी पर चुनें कि कितने और कौन से अंक के पासे हैं और “बोली” पर टैप करें: इसका मतलब है “पूरी मेज़ पर, सबके पासे मिलाकर, इस अंक के कम से कम इतने पासे हैं”। हर बोली पिछली से ऊँची होनी चाहिए: ज़्यादा पासे, या उतने ही पर ऊँचा अंक।\n\n[चुनौती] अगर आपको पिछली बोली पर भरोसा नहीं है, तो “चुनौती!” पर टैप करें। सब अपने पासे दिखाते हैं और उन्हें गिना जाता है: अगर इतने पासे हैं, तो चुनौती देने वाला एक पासा खो देता है; अगर नहीं, तो बोली लगाने वाला एक पासा खो देता है।\n\n[इक्के वाइल्ड] जब टिक किया जाता है, तो एक इक्का किसी भी अंक के रूप में गिना जाता है (इक्कों की बोली में सिर्फ़ इक्के गिने जाते हैं)। पहली बोली इक्कों पर नहीं हो सकती; इक्कों पर जाने के लिए कम से कम आधे पासे चाहिए (ऊपर की ओर पूर्णांकित); इक्कों से वापस जाने के लिए कम से कम दोगुने प्लस एक चाहिए।\n\n[अगला राउंड] जिसने पासा खोया है वह अगले राउंड में पहले बोली लगाता है; अगर उसके पासे ख़त्म हैं, तो अगला खिलाड़ी लगाता है। जिस खिलाड़ी के पास कोई पासा नहीं बचा है वह बाहर है।\n\n[समय ख़त्म] जो खिलाड़ी समय पर पासे नहीं फेंकता या नहीं दिखाता वह राउंड में नहीं खेलता; जो खिलाड़ी बोली के लिए समय पर नहीं है वह बोली होने पर चुनौती देता है, या शुरुआत करने के लिए “1 × 2” की बोली लगाता है। जो खिलाड़ी चुनौती पर अपने पासे नहीं दिखाता वह एक पासा खो देता है।\n\n[निष्पक्ष खेल] कोई भी पासे देख या चुन नहीं सकता, यहाँ तक कि जिसने खेल शुरू किया वह भी नहीं: हर राउंड में हर पेज पहले दो एन्क्रिप्टेड प्रतिबद्धताएँ भेजता है (अपने पासों के लिए एक सीड और एक यादृच्छिक संख्या); सबके भेजने के बाद यादृच्छिक संख्याएँ दिखाई जाती हैं, और हर खिलाड़ी के पासे उनके अपने सीड और सबकी यादृच्छिक संख्याओं से निकलते हैं, इसलिए कोई पहले से अपने अंक नहीं चुन सकता। चुनौती पर सीड दिखाए जाते हैं, और हर पेज प्रतिबद्धताओं की जाँच करके सबके पासे खुद निकालता है।\n\n[सुझाव] पहले अपने पासे गिनें, फिर बाकियों का अनुमान लगाएँ: हर पासा किसी दिए गए अंक को छह में से एक बार दिखाता है (इक्कों के वाइल्ड होने पर तीन में से एक बार)।',
  'rules.button': '📖 खेल के नियम',
  'rules.panel': '📖 नियम',
  'rules.title': 'खेल के नियम',
  'rules.pickAria': 'नियम पढ़ने के लिए एक खेल चुनें',
